def public_detail(request, listing_id):
    # A savepoint cannot give an inherited READ COMMITTED transaction a common
    # snapshot. Keep its caller's original read path and isolation unchanged.
    if connection.in_atomic_block:
        return _native_public_detail(request, listing_id)
    with transaction.atomic():
        with connection.cursor() as cursor:
            cursor.execute("SET TRANSACTION ISOLATION LEVEL REPEATABLE READ READ ONLY")
        with _prepared_page_binding(enabled=True):
            context = PublicationContext(
                DetailQuery(listing_id, timezone.now()), page_read=True, prepared_page=True,
            )
            if not context.rows:
                raise Http404
            listing = context.rows[0]
            if not publicly_visible(listing, context=context):
                raise Http404
        # Render eagerly in the same snapshot: prefetch/guard/presentation must
        # never combine committed versions that were individually ineligible.
        return _public_detail_response(request, listing)


def _native_public_detail(request, listing_id):
    listing = get_object_or_404(
        Listing.objects.select_related("person__agency", "approved_revision"), pk=listing_id
    )
    # Only the native read guard; render and every other caller retain their
    # connection settings. get_object_or_404 above already connected this thread.
    with _prepared_page_binding(enabled=True):
        if not publicly_visible(listing):
            raise Http404
    return _public_detail_response(request, listing)

def results(request):
    form = SearchForm(request.GET, english=request.LANGUAGE_CODE == "en")
    valid = form.is_valid()
    raw_page = request.GET.get("page", "1")
    if len(raw_page) > 6 or not raw_page.isdecimal() or not 1 <= int(raw_page) <= 100000:
        form.add_error(None, "Página inválida / Invalid page")
        valid = False
    number = int(raw_page) if valid else 1
    from apps.catalog.promotion_exposure import enabled as promotions_enabled

    from .public_validation import PublicationContext
    from .publication_state import state_page

    request._publication_route = {"route": "fallback", "reason": "invalid_search"}
    try:
        page = None
        if not valid:
            pass
        else:
            options = {}
            if promotions_enabled():
                from apps.catalog.promotion_paging import order_population

                options["promotion_order"] = partial(
                    order_population, text_search=bool(form.cleaned_data.get("q")),
                )
            page = state_page(candidates(form.cleaned_data), number,
                              checked=form.cleaned_data.get("checked") or (),
                              observation=request._publication_route, **options)
        sponsorship = getattr(page, "sponsorship", {})
        if page is None:
            # The complete native population; its correlated read runs without JIT.
            context = (
                PublicationContext(candidates(form.cleaned_data), page_read=True)
                if valid else None
            )
            visible = (
                [listing for listing in context.rows
                 if publicly_visible(listing, context=context)
                 and matches_checks(listing.person, form.cleaned_data.get("checked"))]
                if context else []
            )
            from apps.catalog.promotion_exposure import ranked

            visible, sponsorship = ranked(visible, text_search=bool(form.cleaned_data.get("q")))
            page = Paginator(visible, 24).page(number)

